# -*- coding: utf-8 -*-
import base64
import zlib
import sys
import os

# Encrypted content
_data = ""

def run():
    try:
        # Add script directory to sys.path to find local modules
        script_dir = os.path.dirname(os.path.abspath(__file__))
        if script_dir not in sys.path:
            sys.path.insert(0, script_dir)
        
        # Set working directory to script directory
        os.chdir(script_dir)

        # Decode and Decompress in memory
        decoded = base64.b64decode(_data)
        decompressed = zlib.decompress(decoded)
        
        # Execute the code with proper globals
        namespace = {
            "__name__": "__main__",
            "__file__": os.path.join(script_dir, "kakaotalk.py"),
            "__builtins__": __builtins__,
        }
        exec(decompressed.decode('utf-8'), namespace)
    except Exception as e:
        import traceback
        error_msg = traceback.format_exc()
        print(f"Error loading program:\n{error_msg}")
        try:
            import ctypes
            ctypes.windll.user32.MessageBoxW(0, f"프로그램 실행 중 오류가 발생했습니다:\n{e}", "오류", 0x10)
        except: pass

if __name__ == "__main__":
    run()
